package com.agacostays.payroll.mapper; import com.agacostays.payroll.entity.Payroll; import com.agacostays.payroll.dto.response.PayrollResponse; import org.springframework.stereotype.Component; @Component public class PayrollMapper{public PayrollResponse toResponse(Payroll x){return new PayrollResponse(x.getPayrollId(),x.getBranchId(),x.getStaffId(),x.getRoleId(),x.getDepartment(),x.getMonth(),x.getYear(),x.getTotalWorkingDays(),x.getPresentDays(),x.getAbsentDays(),x.getHalfDays(),x.getLeaveDays(),x.getBasicSalary(),x.getHra(),x.getAllowances(),x.getBonus(),x.getGrossSalary(),x.getAttendanceDeduction(),x.getOtherDeductions(),x.getNetSalary(),x.getPaymentStatus().name(),x.getPaymentMode().name(),x.getTransactionId(),x.getPaidAt(),x.getRemarks(),x.getGeneratedBy(),x.getCreatedAt(),x.getUpdatedAt());}}